// Opening book from lichess-org/chess-openings (CC0), generated by scripts/build-openings.ts.
import data from "./openings.json";

const book = data as { n: string[]; p: Record<string, number> };

/** Placement, side to move and castling only: the en-passant field is ignored (design D7). */
export const bookKey = (fen: string) => fen.split(" ").slice(0, 3).join(" ");

export function lookupOpening(fen: string): { eco: string; name: string } | null {
  const i = book.p[bookKey(fen)];
  const entry = i === undefined ? undefined : book.n[i];
  if (!entry) return null;
  const [eco = "", name = ""] = entry.split("|");
  return { eco, name };
}

export function isBook(fen: string): boolean {
  return bookKey(fen) in book.p;
}
